		}
		json.NewDecoder(r.Body).Decode(&body)
		user := User{ID: nextUserID, Username: body.Username, Email: body.Email}
		nextUserID++
		users = append(users, user)
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(user)
		return
