package main

import (
	"encoding/json"
	"net/http"
	"os"
	"strconv"
	"strings"
)

type User struct {
	ID        int    `json:"id"`
	Username  string `json:"username"`
	Email     string `json:"email"`
	Followers []int  `json:"followers"`
	Following []int  `json:"following"`
}

var (
	users       []User
	nextUserID  = 1
)

func usersHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	path := strings.TrimPrefix(r.URL.Path, "/api/users")

	if path == "" || path == "/" {
		var body struct {
			Username string `json:"username"`
			Email    string `json:"email"`
		}
		json.NewDecoder(r.Body).Decode(&body)
		user := User{ID: nextUserID, Username: body.Username, Email: body.Email}
		nextUserID++
		users = append(users, user)
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(user)
		return
	}

	parts := strings.Split(strings.Trim(path, "/"), "/")
	id, err := strconv.Atoi(parts[0])
	if err != nil {
		http.NotFound(w, r)
		return
	}

	if len(parts) == 1 {
		for _, u := range users {
			if u.ID == id {
				json.NewEncoder(w).Encode(u)
				return
			}
		}
		http.NotFound(w, r)
		return
	}

	if len(parts) == 2 && parts[1] == "follow" {
		var body struct {
			UserID int `json:"userId"`
		}
		json.NewDecoder(r.Body).Decode(&body)
		var target, follower *User
		for i := range users {
			if users[i].ID == id {
				target = &users[i]
			}
			if users[i].ID == body.UserID {
				follower = &users[i]
			}
		}
		if target == nil || follower == nil {
			w.WriteHeader(http.StatusNotFound)
			json.NewEncoder(w).Encode(map[string]string{"error": "User not found"})
			return
		}
		found := false
		for _, f := range target.Followers {
			if f == body.UserID {
				found = true
				break
			}
		}
		if !found {
			target.Followers = append(target.Followers, body.UserID)
		}
		found = false
		for _, f := range follower.Following {
			if f == id {
				found = true
				break
			}
		}
		if !found {
			follower.Following = append(follower.Following, id)
		}
		json.NewEncoder(w).Encode(map[string]bool{"success": true})
	}
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}

	http.HandleFunc("/api/users", usersHandler)
	http.HandleFunc("/api/users/", usersHandler)

	http.ListenAndServe(":"+port, nil)
}

