		return
	}

	id, err := strconv.Atoi(parts[0])
	if err != nil {
		http.NotFound(w, r)
		return
	}

	var body struct {
		UserID int `json:"userId"`
	}
	json.NewDecoder(r.Body).Decode(&body)

	for i, p := range posts {
		if p.ID == id {
			found := false
			for _, l := range posts[i].Likes {
				if l == body.UserID {
					found = true
					break
				}
			}
			if !found {
				posts[i].Likes = append(posts[i].Likes, body.UserID)
			}
			json.NewEncoder(w).Encode(posts[i])
			return
		}
	}
	http.NotFound(w, r)
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}

	http.HandleFunc("/api/posts/", postsHandler)

	http.ListenAndServe(":"+port, nil)
}
